#!/usr/bin/env bash
# Run the docs.python.org redirects specs against a local nginx instance that
# uses the salt-managed redirect configuration.
#
# Requirements: nginx and hurl must be installed and available on PATH.
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")"

command -v nginx >/dev/null 2>&1 || {
    echo "nginx is required to run the docs-redirects specs" >&2
    exit 1
}
command -v hurl >/dev/null 2>&1 || {
    echo "hurl is required to run the docs-redirects specs" >&2
    exit 1
}

port="${PORT:-8088}"
workdir="$(mktemp -d)"

cleanup() {
    if [ -f "$workdir/nginx.pid" ]; then
        nginx -p "$workdir" -c nginx.conf -s quit >/dev/null 2>&1 || true
    fi
    rm -rf "$workdir"
}
trap cleanup EXIT

# The redirect layout is the same file that salt deploys to
# /etc/nginx/sites.d/docs/redirects.conf.
cp ../salt/docs/config/nginx.docs-redirects.conf "$workdir/redirects.conf"

# Stub out the doc tree files that the specs request so the responses are 200.
root="$workdir/root"
mkdir -p "$root/3" "$root/dev" "$root/es/3" "$root/fr/3.12" "$root/pt-br/dev"
touch "$root/3/index.html" "$root/3/about.html" "$root/3/objects.inv" \
    "$root/dev/index.html" "$root/es/3/index.html" \
    "$root/fr/3.12/index.html" "$root/pt-br/dev/index.html"

cat > "$workdir/nginx.conf" <<EOF
pid        $workdir/nginx.pid;
error_log  $workdir/error.log warn;

events {
    worker_connections 1024;
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;
    access_log    off;

    server {
        listen       $port;
        server_name  docs.python.org;
        root         $root;
        autoindex    on;

        include $workdir/redirects.conf;
    }
}
EOF

nginx -p "$workdir" -c nginx.conf

for _ in $(seq 1 50); do
    [ -f "$workdir/nginx.pid" ] && kill -0 "$(cat "$workdir/nginx.pid")" 2>/dev/null && break
    sleep 0.1
done

hurl --test --variable host="http://127.0.0.1:$port" specs/*.hurl

