# Add a Surrogate-Key header so that the CDN can purge a single
    # language/version pair of the docs (e.g. only the French 3.12 docs, or
    # only the English dev docs) instead of invalidating every cached
    # response. The key mirrors the language and version segments of the
    # requested path (en/3, fr/3.12, pt-br/dev, ...). These blocks are kept
    # after every redirect rule above so they only attach a header and never
    # change redirect behavior. Versions are enumerated explicitly: no
    # wildcard is used for Python 3.13 or later. Surrogate-Control is
    # repeated because nginx does not inherit server-level add_header
    # directives from a location that defines its own.
    location ~ ^/(es|fr|id|it|ja|ko|pl|pt-br|tr|uk|zh-cn|zh-tw)/(2|2\.[0-9]|3|3\.[0-8]|3\.9|3\.1[0-2]|dev)/ {
        add_header Surrogate-Control max-age=604800;
        add_header Surrogate-Key $1/$2;
    }
    location ~ ^/(2|2\.[0-9]|3|3\.[0-8]|3\.9|3\.1[0-2]|dev)/ {
        add_header Surrogate-Control max-age=604800;
        add_header Surrogate-Key en/$1;
    }

